#pragma warning disable IDE0130
#pragma warning disable IDE0290

using Barotrauma;
using Microsoft.Xna.Framework;

using BGUI = Barotrauma.GUI;

namespace SOS.GUI
{
    /// <summary>
    /// Flags indicating which edges/corners of a frame can be resized.
    /// </summary>
    /// <remarks>
    /// Used by <see cref="GUIResizableFrame"/> to determine which resize handles are active.
    /// Can be combined using bitwise OR (e.g., <c>ResizeDirection.Top | ResizeDirection.Right</c>).
    /// </remarks>
    [Flags]
    public enum ResizeDirection
    {
        /// <summary>No resize directions allowed.</summary>
        None = 0,
        /// <summary>Can resize from the top edge.</summary>
        Top = 1,
        /// <summary>Can resize from the bottom edge.</summary>
        Bottom = 2,
        /// <summary>Can resize from the left edge.</summary>
        Left = 4,
        /// <summary>Can resize from the right edge.</summary>
        Right = 8,
        /// <summary>Can resize horizontally (left and right edges).</summary>
        Horizontal = Left | Right,
        /// <summary>Can resize vertically (top and bottom edges).</summary>
        Vertical = Top | Bottom,
        /// <summary>Can resize from all edges and corners.</summary>
        All = Top | Bottom | Left | Right
    }

    /// <summary>
    /// A resizable and draggable frame component with configurable resize directions and bounds clamping.
    /// </summary>
    /// <remarks>
    /// Supports mouse-based resizing from edges and corners, with optional symmetric resizing (Shift),
    /// aspect ratio preservation (Shift on corner), and parent bounds clamping.
    /// Also supports dragging the frame by its title area (top 50px by default).
    /// </remarks>
    public class GUIResizableFrame : GUIFrame
    {
        /// <summary>
        /// Gets or sets the allowed resize directions for this frame.
        /// </summary>
        /// <remarks>
        /// Defaults to <see cref="ResizeDirection.All"/>. Can be restricted to specific edges or combinations.
        /// </remarks>
        public ResizeDirection AllowedDirections { get; set; } = ResizeDirection.All;

        /// <summary>
        /// Gets or sets whether the frame's position and size should be clamped to its parent bounds.
        /// </summary>
        /// <remarks>
        /// Defaults to <c>true</c>. When <c>false</c>, the frame can be resized/moved outside its parent.
        /// </remarks>
        public bool ClampToParentBounds { get; set; } = true;

        /// <summary>
        /// Gets or sets whether resizing should be symmetric (expand equally in opposite directions).
        /// </summary>
        /// <remarks>
        /// Defaults to <c>false</c>. When <c>true</c>, resizing from one edge also resizes the opposite edge.
        /// Can be temporarily overridden by holding Alt during resize.
        /// </remarks>
        public bool ForceSymmetric { get; set; } = false;

        /// <summary>
        /// Gets or sets whether the frame is fixed (cannot be resized or moved).
        /// </summary>
        /// <remarks>
        /// Defaults to <c>false</c>. When <c>true</c>, disables all resize and move interactions.
        /// </remarks>
        public bool IsFixed { get; set; } = false;

        /// <summary>
        /// Gets or sets the margin (in pixels) around the frame edges where resize handles are active.
        /// </summary>
        /// <remarks>
        /// Defaults to 12 pixels. The hit detection area extends this margin beyond the frame's visual bounds.
        /// </remarks>
        public int ResizeMargin { get; set; } = 12;

        /// <summary>
        /// Gets whether the frame can be moved by dragging its title area.
        /// </summary>
        /// <remarks>
        /// Defaults to <c>true</c>. Can be overridden in derived classes to disable moving.
        /// </remarks>
        public virtual bool CanMove => true;

        /// <summary>
        /// Gets the height of the draggable title area at the top of the frame.
        /// </summary>
        /// <remarks>
        /// Defaults to 50 pixels. TODO: This is temporary and should be replaced with invisible buttons.
        /// </remarks>
        protected virtual int DragAreaHeight => 50; //TODO: Temporal, dee ser cambiado por botones invisibles a futuro.

        private bool isDragging;
        private bool isMoving;
        private ResizeDirection currentDragDir;
        private Vector2 dragStartMouse;
        private Rectangle startRect;
        private Point startOffset;
        private float startAspectRatio;
        private bool wasMouseDown;

        /// <summary>
        /// Creates a new resizable frame.
        /// </summary>
        /// <param name="rectT">The rectangle transform for positioning and sizing.</param>
        /// <param name="style">The GUI style name. Defaults to empty string.</param>
        /// <param name="color">The frame color. Defaults to null (uses style default).</param>
        /// <remarks>
        /// Sets <c>CanBeFocused</c> to <c>true</c> to enable mouse interaction.
        /// </remarks>
        public GUIResizableFrame(RectTransform rectT, string style = "", Color? color = null)
            : base(rectT, style, color)
        {
            CanBeFocused = true;
        }

        /// <summary>
        /// Updates the frame, handling mouse interactions for resizing and dragging.
        /// </summary>
        /// <param name="deltaTime">Time elapsed since the last update in seconds.</param>
        /// <remarks>
        /// Handles three interaction states:
        /// <list type="bullet">
        /// <item><term>Idle:</term><description>Detects hover over resize edges/corners (within <see cref="ResizeMargin"/>)
        /// or title area. Updates cursor to indicate available interaction.</description></item>
        /// <item><term>Dragging (resizing):</term><description>Resizes the frame based on mouse movement.
        /// Supports corner resizing with aspect ratio preservation (Shift), symmetric resizing (Shift on edge,
        /// Alt for temporary symmetric), and parent bounds clamping.</description></item>
        /// <item><term>Moving:</term><description>Moves the frame by dragging the title area (top <see cref="DragAreaHeight"/> pixels).
        /// Ignores interactive child elements (buttons, text boxes, dropdowns, list boxes).</description></item>
        /// </list>
        /// </remarks>
        public override void Update(float deltaTime)
        {
            base.Update(deltaTime);
            if (!Visible) return;

            Vector2 mousePos = PlayerInput.MousePosition;
            bool isMouseHeld = PlayerInput.PrimaryMouseButtonHeld();
            bool isMouseDownNow = isMouseHeld && !wasMouseDown;

            if (!isDragging && !isMoving)
            {
                currentDragDir = GetHoverDirection(mousePos, Rect) & AllowedDirections;

                bool inTitleArea = CanMove && !IsFixed && Rect.Contains(mousePos) && mousePos.Y < Rect.Y + DragAreaHeight;

                if (currentDragDir != ResizeDirection.None)
                {
                    bool isCorner = IsCorner(currentDragDir);
                    bool isShift = PlayerInput.IsShiftDown();

                    BGUI.MouseCursor = (!isCorner && isShift && !IsFixed) ? CursorState.Hand : CursorState.Move;

                    if (isMouseDownNow)
                    {
                        isDragging = true;
                        dragStartMouse = mousePos;
                        startRect = Rect;
                        startOffset = RectTransform.AbsoluteOffset;
                        startAspectRatio = (float)startRect.Width / startRect.Height;
                        BGUI.ForceMouseOn(this);
                    }
                }
                else if (inTitleArea)
                {
                    bool onInteractive = BGUI.MouseOn is GUIButton or GUITextBox or GUIDropDown or GUIListBox;

                    if (BGUI.MouseOn != null && (BGUI.MouseOn == this || IsParentOf(BGUI.MouseOn)) && !onInteractive)
                    {
                        BGUI.MouseCursor = CursorState.Hand;
                        if (isMouseDownNow)
                        {
                            isMoving = true;
                            dragStartMouse = mousePos;
                            startOffset = RectTransform.AbsoluteOffset;
                            BGUI.ForceMouseOn(this);
                        }
                    }
                }
            }
            else if (isDragging)
            {
                BGUI.MouseCursor = CursorState.Dragging;
                if (!isMouseHeld) { isDragging = false; return; }
                ApplyInteraction(mousePos);
            }
            else if (isMoving)
            {
                BGUI.MouseCursor = CursorState.Dragging;
                if (!isMouseHeld) { isMoving = false; return; }

                float deltaX = mousePos.X - dragStartMouse.X;
                float deltaY = mousePos.Y - dragStartMouse.Y;
                RectTransform.AbsoluteOffset = new Point((int)(startOffset.X + deltaX), (int)(startOffset.Y + deltaY));
            }
            wasMouseDown = isMouseHeld;
        }

        /// <summary>
        /// Applies the resize or move interaction based on the current drag direction and mouse position.
        /// </summary>
        /// <param name="mousePos">The current mouse position.</param>
        /// <remarks>
        /// Handles two main interaction modes:
        /// <list type="bullet">
        /// <item><term>Move (non-corner + Shift):</term><description>Moves the frame by updating the absolute offset.
        /// Clamps to parent bounds if <see cref="ClampToParentBounds"/> is true.</description></item>
        /// <item><term>Resize:</term><description>Calculates new width/height based on drag direction and delta.
        /// Supports symmetric resizing (<see cref="ForceSymmetric"/> or Alt), aspect ratio preservation
        /// (corner + Shift), min/max size limits, and parent bounds clamping.</description></item>
        /// </list>
        /// The pivot point of the frame affects how the position is adjusted during resize.
        /// </remarks>
        private void ApplyInteraction(Vector2 mousePos)
        {
            float deltaX = mousePos.X - dragStartMouse.X;
            float deltaY = mousePos.Y - dragStartMouse.Y;

            if (Math.Abs(deltaX) < 0.01f && Math.Abs(deltaY) < 0.01f) return;

            bool isCorner = IsCorner(currentDragDir);
            bool isShift = PlayerInput.IsShiftDown();
            bool isAlt = PlayerInput.IsAltDown();
            bool isSymmetric = ForceSymmetric || isAlt;

            if (!isCorner && isShift && !IsFixed)
            {
                int newX = (int)(startOffset.X + deltaX);
                int newY = (int)(startOffset.Y + deltaY);

                if (ClampToParentBounds && RectTransform.Parent != null)
                {
                    Rectangle pRect = RectTransform.ParentRect;
                    Rectangle myRect = new(Rect.X + (newX - RectTransform.AbsoluteOffset.X),
                                                   Rect.Y + (newY - RectTransform.AbsoluteOffset.Y),
                                                   Rect.Width, Rect.Height);

                    if (myRect.Left < pRect.Left) newX += (pRect.Left - myRect.Left);
                    if (myRect.Right > pRect.Right) newX -= (myRect.Right - pRect.Right);
                    if (myRect.Top < pRect.Top) newY += (pRect.Top - myRect.Top);
                    if (myRect.Bottom > pRect.Bottom) newY -= (myRect.Bottom - pRect.Bottom);
                }

                RectTransform.AbsoluteOffset = new Point(newX, newY);
                return;
            }

            float rawDeltaX = 0, rawDeltaY = 0;

            if (currentDragDir.HasFlag(ResizeDirection.Right)) rawDeltaX = deltaX;
            else if (currentDragDir.HasFlag(ResizeDirection.Left)) rawDeltaX = -deltaX;

            if (currentDragDir.HasFlag(ResizeDirection.Bottom)) rawDeltaY = deltaY;
            else if (currentDragDir.HasFlag(ResizeDirection.Top)) rawDeltaY = -deltaY;

            if (isSymmetric) { rawDeltaX *= 2; rawDeltaY *= 2; }

            float targetW = startRect.Width + rawDeltaX;
            float targetH = startRect.Height + rawDeltaY;

            bool maintainRatio = isCorner && isShift;
            if (maintainRatio)
            {
                if (Math.Abs(rawDeltaX) / startRect.Width > Math.Abs(rawDeltaY) / startRect.Height)
                    targetH = targetW / startAspectRatio;
                else
                    targetW = targetH * startAspectRatio;
            }

            Point minLimit = RectTransform.MinSize;
            Point maxLimit = RectTransform.MaxSize;
            int limitWX = maxLimit.X <= 0 ? int.MaxValue : maxLimit.X;
            int limitHY = maxLimit.Y <= 0 ? int.MaxValue : maxLimit.Y;

            targetW = MathHelper.Clamp(targetW, minLimit.X, limitWX);
            targetH = MathHelper.Clamp(targetH, minLimit.Y, limitHY);

            if (ClampToParentBounds && RectTransform.Parent != null)
            {
                Rectangle pRect = RectTransform.ParentRect;
                float maxGrowR = pRect.Right - startRect.Right;
                float maxGrowL = startRect.Left - pRect.Left;
                float maxGrowB = pRect.Bottom - startRect.Bottom;
                float maxGrowT = startRect.Top - pRect.Top;

                if (currentDragDir.HasFlag(ResizeDirection.Right) && (targetW - startRect.Width) > maxGrowR) targetW = startRect.Width + maxGrowR;
                if (currentDragDir.HasFlag(ResizeDirection.Left) && (targetW - startRect.Width) > maxGrowL) targetW = startRect.Width + maxGrowL;
                if (currentDragDir.HasFlag(ResizeDirection.Bottom) && (targetH - startRect.Height) > maxGrowB) targetH = startRect.Height + maxGrowB;
                if (currentDragDir.HasFlag(ResizeDirection.Top) && (targetH - startRect.Height) > maxGrowT) targetH = startRect.Height + maxGrowT;

                if (maintainRatio)
                {
                    if (targetW / startRect.Width < targetH / startRect.Height) targetH = targetW / startAspectRatio;
                    else targetW = targetH * startAspectRatio;
                }
            }

            float finalCX = targetW - startRect.Width;
            float finalCY = targetH - startRect.Height;
            float moveL = 0, moveT = 0;

            if (isSymmetric) { moveL = -finalCX / 2f; moveT = -finalCY / 2f; }
            else
            {
                if (currentDragDir.HasFlag(ResizeDirection.Left)) moveL = -finalCX;
                if (currentDragDir.HasFlag(ResizeDirection.Top)) moveT = -finalCY;
            }

            Vector2 pivot = GetPivotVector(RectTransform.Pivot);
            RectTransform.NonScaledSize = new Point((int)Math.Round(targetW), (int)Math.Round(targetH));
            RectTransform.AbsoluteOffset = new Point(
                (int)Math.Round(startOffset.X + moveL + finalCX * pivot.X),
                (int)Math.Round(startOffset.Y + moveT + finalCY * pivot.Y)
            );
        }

        /// <summary>
        /// Determines if a resize direction represents a corner (combination of horizontal and vertical).
        /// </summary>
        /// <param name="dir">The resize direction to check.</param>
        /// <returns><c>true</c> if the direction includes both horizontal and vertical components; <c>false</c> otherwise.</returns>
        /// <remarks>
        /// A corner direction has at least one horizontal flag (Left or Right) and at least one
        /// vertical flag (Top or Bottom) set.
        /// </remarks>
        private static bool IsCorner(ResizeDirection dir) =>
            (dir.HasFlag(ResizeDirection.Left) || dir.HasFlag(ResizeDirection.Right)) &&
            (dir.HasFlag(ResizeDirection.Top) || dir.HasFlag(ResizeDirection.Bottom));

        /// <summary>
        /// Determines which resize direction the mouse is hovering over.
        /// </summary>
        /// <param name="mouse">The mouse position.</param>
        /// <param name="rect">The frame's rectangle.</param>
        /// <returns>The resize direction(s) the mouse is over, or <see cref="ResizeDirection.None"/> if outside the detection margin.</returns>
        /// <remarks>
        /// The detection area is the frame rectangle inflated by <see cref="ResizeMargin"/> on all sides.
        /// Checks proximity to each edge within the margin to determine the direction.
        /// </remarks>
        private ResizeDirection GetHoverDirection(Vector2 mouse, Rectangle rect)
        {
            Rectangle detectRect = rect;
            detectRect.Inflate(ResizeMargin, ResizeMargin);
            if (!detectRect.Contains(mouse.ToPoint())) return ResizeDirection.None;

            ResizeDirection dir = ResizeDirection.None;
            if (Math.Abs(mouse.X - rect.Left) <= ResizeMargin) dir |= ResizeDirection.Left;
            else if (Math.Abs(mouse.X - rect.Right) <= ResizeMargin) dir |= ResizeDirection.Right;
            if (Math.Abs(mouse.Y - rect.Top) <= ResizeMargin) dir |= ResizeDirection.Top;
            else if (Math.Abs(mouse.Y - rect.Bottom) <= ResizeMargin) dir |= ResizeDirection.Bottom;
            return dir;
        }

        /// <summary>
        /// Converts a <see cref="Pivot"/> enum to a normalized vector representing the pivot point.
        /// </summary>
        /// <param name="pivot">The pivot to convert.</param>
        /// <returns>A vector where (0,0) is top-left and (1,1) is bottom-right.</returns>
        /// <remarks>
        /// Used during resize to calculate how the frame's position should shift based on its pivot point.
        /// </remarks>
        private static Vector2 GetPivotVector(Pivot pivot) => pivot switch
        {
            Pivot.TopLeft => new Vector2(0, 0),
            Pivot.TopCenter => new Vector2(0.5f, 0),
            Pivot.TopRight => new Vector2(1, 0),
            Pivot.CenterLeft => new Vector2(0, 0.5f),
            Pivot.Center => new Vector2(0.5f, 0.5f),
            Pivot.CenterRight => new Vector2(1, 0.5f),
            Pivot.BottomLeft => new Vector2(0, 1),
            Pivot.BottomCenter => new Vector2(0.5f, 1),
            Pivot.BottomRight => new Vector2(1, 1),
            _ => Vector2.Zero
        };
    }
}